import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int limit = Integer.parseInt(in.nextLine().trim());
        String line = in.hasNextLine() ? in.nextLine().trim() : "";
        String[] parts = line.isEmpty() ? new String[0] : line.split("\\s+");
        int[] factors = new int[parts.length];
        for (int i = 0; i < parts.length; i++) factors[i] = Integer.parseInt(parts[i]);
        long sum = 0;
        for (int k = 1; k < limit; k++) {
            boolean multiple = false;
            for (int f : factors) if (f != 0 && k % f == 0) multiple = true;
            if (multiple) sum += k;
        }
